  }

  if (app_config::kWebSocketEnabled && !websocketStarted_) {
    startWebSocket();
  }

  if (websocketStarted_) {
    websocket_.loop();
  }

  if (nowMs - lastPollMs_ >= app_config::kStatusPollIntervalMs) {
    pollStatus(nowMs);
  }
}

