2	
3	export type AttackStatus =
4	  | "Devin processing"
5	  | "Devin fixing"
6	  | "Devin verifying"
7	  | "Devin deploying"
8	  | "Fix deployed";
9	
10	export interface AttackRecord {
11	  id: number;
12	  ts: number;
13	  nodeId: string;
14	  name: string;
15	  packetCount: number;
16	  status: AttackStatus;
17	  events: TimelineLine[]; // this incident's own thread, oldest -> newest
18	}
19	
20	export interface AttackPacket {
21	  id: string;
22	  nodeId: string;
23	  frameType: string;
24	  match: string;
25	}
26	
27	const STATUS_BY_EVENT: Partial<Record<EventType, AttackStatus>> = {
28	  ANOMALY_DETECTED: "Devin processing",
29	  AGENT_ANALYZING: "Devin processing",
30	  FILTER_GENERATED: "Devin fixing",
31	  VERIFYING: "Devin verifying",
32	  VERIFY_FAILED: "Devin verifying",
33	  VERIFY_PASSED: "Devin verifying",
34	  OTA_DEPLOYING: "Devin deploying",
35	  DEPLOYED: "Fix deployed",
36	  FRAME_BLOCKED: "Fix deployed",
37	};
38	
39	export function selectFrameFeed(timeline: TimelineLine[], limit: number): TimelineLine[] {
40	  // `timeline` is newest-first; show the most recent `limit` in chronological
41	  // order (oldest at top, newest at the bottom) so the defense loop reads top-down.
42	  return timeline.slice(0, Math.max(0, limit)).reverse();
43	}
44	
45	function parsePacketCount(text: string): number {
46	  const match = text.match(/([\d,]+)\s+(?:attack\s+)?frames?/i);
47	  return match ? Number(match[1].replaceAll(",", "")) : 1;
48	}
49	
50	function parseAttackClass(lines: TimelineLine[]): string | undefined {
51	  const generated = lines.find((line) => line.type === "FILTER_GENERATED");
52	  return generated?.text.match(/generated:\s*([a-z\d_ -]+)/i)?.[1]?.trim();
53	}
54	
55	function formatAttackName(value?: string | null): string {
56	  if (!value) return "Frame flood";
57	  const words = value.replaceAll("_", " ").trim();
58	  return words.charAt(0).toUpperCase() + words.slice(1);
59	}
60	
61	export function selectAttackHistory(timeline: TimelineLine[], activeAttack: string | null): AttackRecord[] {
62	  const anomalyIndexes = timeline.flatMap((line, index) => (line.type === "ANOMALY_DETECTED" ? [index] : []));
63	
64	  return anomalyIndexes.map((index, attackIndex) => {
65	    const segmentStart = attackIndex === 0 ? 0 : anomalyIndexes[attackIndex - 1] + 1;
66	    const anomaly = timeline[index];
67	    const related = timeline
68	      .slice(segmentStart, index + 1)
69	      .filter((line) => line.node_id === anomaly.node_id);
70	    const status = related.map((line) => STATUS_BY_EVENT[line.type]).find(Boolean) ?? "Devin processing";
71	    const attackClass = parseAttackClass(related) ?? (attackIndex === 0 ? activeAttack : null);
72	
73	    return {
74	      id: anomaly.id,
75	      ts: anomaly.ts,
76	      nodeId: anomaly.node_id ?? "system",
77	      name: formatAttackName(attackClass),
78	      packetCount: parsePacketCount(anomaly.text),
79	      status,
80	      events: related.slice().reverse(), // oldest -> newest for a readable thread
81	    };
82	  });
83	}
84	
85	export function selectAttackPackets(attack: AttackRecord, limit = 6): AttackPacket[] {
86	  const count = Math.min(Math.max(0, limit), attack.packetCount);
87	  const frameType = /deauth/i.test(attack.name) ? "Deauthentication" : "Matched frame";
88	
89	  return Array.from({ length: count }, (_, index) => ({
90	    id: `PKT-${String(attack.id).padStart(4, "0")}-${String(index + 1).padStart(3, "0")}`,
91	    nodeId: attack.nodeId,
92	    frameType,
93	    match: "Linked signature",
94	  }));
95	}
