297	void send_one_packet() {
298	    const auto plan = red_esp::make_packet_plan(
299	        attack_config.mode,
300	        sent_packets,
301	        base_sender_id
302	    );
303	    std::uint8_t embedded[demo_protocol::kMaxEmbeddedFrameSize]{};
304	    std::size_t embedded_size = 0U;
305	    if (attack_config.mode == AttackMode::deauth_simulation) {
306	        embedded_size = demo_protocol::make_synthetic_deauth_frame(
307	            sender_mac,
