309	            embedded,
310	            sizeof(embedded)
311	        );
312	    } else {
313	        embedded_size = red_esp::encode_packet(
314	            attack_config.mode,
315	            run_id,
316	            plan,
317	            millis(),
318	            embedded,
319	            sizeof(embedded)
320	        );
321	    }
322	
323	    std::uint8_t envelope[demo_protocol::kMaxPacketSize]{};
324	    const auto scenario = static_cast<demo_protocol::Scenario>(
325	        static_cast<std::uint8_t>(attack_config.mode)
326	    );
