352	void tick_attack() {
353	    if (!running) {
354	        return;
355	    }
356	    if (WiFi.status() != WL_CONNECTED) {
357	        stop_attack("hotspot disconnected");
358	        return;
359	    }
360	    const std::uint32_t elapsed_ms = millis() - attack_started_ms;
361	    const std::uint32_t budget =
362	        static_cast<std::uint32_t>(attack_config.packets_per_second) *
363	        static_cast<std::uint32_t>(attack_config.duration_seconds);
364	    if (elapsed_ms >= static_cast<std::uint32_t>(attack_config.duration_seconds) * 1000U ||
365	        sent_packets >= budget) {
366	        stop_attack("limit reached");
367	        return;
368	    }
369	
370	    const std::uint32_t interval_us = 1000000U / attack_config.packets_per_second;
371	    unsigned burst_guard = 0U;
372	    while (static_cast<std::int32_t>(micros() - next_send_us) >= 0 && burst_guard < 4U) {
373	        send_one_packet();
374	        next_send_us += interval_us;
375	        ++burst_guard;
376	        if (sent_packets >= budget) {
377	            break;
378	        }
379	    }
380	}
