139	        capture.started_ms = millis();
140	    }
141	    capture.logical_count += frame.logical_count;
142	    total_frames_seen += frame.logical_count;
143	    last_attack_ms = millis();
144	    if (capture.frame_count < kCapturedFramesPerWindow) {
145	        const std::uint8_t index = capture.frame_count++;
146	        capture.frame_lengths[index] = frame.frame_length;
147	        std::memcpy(capture.frames[index], frame.frame, frame.frame_length);
148	    }
