.command-lead {
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 0;
  overflow: hidden;
  border: var(--landing-border);
  background: #fff;
  box-shadow: var(--landing-shadow);
  color: #151515;
  cursor: pointer;
  text-align: left;
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.command-lead:hover,
.command-lead:focus-visible {
  outline: none;
  transform: translate(4px, 4px);
  box-shadow: 4px 4px 0 #151515;
}

.command-lead-top {
  min-height: 46px;
  display: flex;
  align-items: center;
  justify-content: space-between;
