}

.command-lead-body {
  display: grid;
  grid-template-columns: minmax(240px, 340px) minmax(0, 1fr);
}

.command-lead-art {
  position: relative;
  overflow: hidden;
  border-right: var(--landing-border);
  background: #fff;
}

.command-lead-art img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: 50% 50%;
  transition: transform 260ms ease;
}

.command-lead:hover .command-lead-art img { transform: scale(1.035); }

.command-lead-copy {
  display: flex;
  flex-direction: column;
  padding: 30px 30px 24px;
}

.command-lead-copy strong {
  margin-bottom: 16px;
  font-family: Impact, Haettenschweiler, "Arial Narrow Bold", sans-serif;
  font-size: clamp(56px, 7vw, 104px);
  font-weight: 900;
  line-height: 0.82;
  letter-spacing: -0.03em;
}

.command-lead-copy > span {
  font-size: clamp(20px, 2.4vw, 30px);
  font-weight: 850;
  line-height: 1.08;
  letter-spacing: -0.035em;
}

.command-lead-copy small {
  margin-top: 14px;
  max-width: 620px;
  color: #6f6b64;
  font-size: 13px;
  line-height: 1.5;
}

.command-lead-open {
  margin: 26px 0 0;
}

/* The link from the coordinator down to the crew it directs. */
.crew-connector {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  margin: 0 0 4px;
}

.crew-connector::before {
  content: "";
  width: 3px;
  height: 34px;
  background: #151515;
}

.crew-connector span {
  margin-top: -1px;
  padding: 8px 16px;
  border: var(--landing-border);
  background: #151515;
  color: #fff;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.16em;
}

.crew-connector::after {
  content: "▼";
  margin-top: 8px;
  font-size: 13px;
  line-height: 1;
  color: #151515;
}

.crew-grid {
  margin-top: 12px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.method-section {
